"""C364 modern Hopfield associative retrieval for monthly ETF allocation.

Paper (CC BY 4.0 preprint): Nicolini, Gopalan, Staiano, and Lepri (2024),
Hopfield Networks for Asset Allocation, https://arxiv.org/abs/2407.17645
Full paper (CC BY 4.0): https://arxiv.org/html/2407.17645v1
Research references (ideas only):
  hopfield-layers (BSD 3-clause-style, including PyTorch-derived portions)
  https://github.com/ml-jku/hopfield-layers
  https://github.com/ml-jku/hopfield-layers/blob/master/LICENSE
  https://github.com/ml-jku/hopfield-layers/blob/master/hflayers/__init__.py
  https://github.com/ml-jku/hopfield-layers/blob/master/hflayers/functional.py
  skfolio (BSD-3-Clause)
  https://github.com/skfolio/skfolio
  https://github.com/skfolio/skfolio/blob/main/src/skfolio/model_selection/_combinatorial.py
Data source: Yahoo Finance daily data embedded in config.yaml under data.snapshots.
"""

import gzip
import hashlib
import json
import signal
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml


SESSIONS_PER_YEAR = 252
PRICE_ADJUSTMENT = (
    "Yahoo Finance split-adjusted Open and Close (yfinance auto_adjust=False), "
    "forward total returns with cash distributions reinvested at ex-date open"
)


def load_raw(settings):
    symbols = sorted({*settings["universe"], settings["risk_free"]})
    start = pd.Timestamp(settings["dates"]["data_start"]).date().isoformat()
    end = (pd.Timestamp(settings["dates"]["end"]) + pd.Timedelta(days=1)).date().isoformat()
    request_key = "|".join([*symbols, start, end, "daily-with-actions"])
    request_hash = hashlib.sha256(request_key.encode("utf-8")).hexdigest()[:16]
    snapshot_name = f"yahoo_{request_hash}.csv"
    snapshot = settings["data"]["snapshots"][snapshot_name]
    raw = gzip.decompress(snapshot["gzip"])
    snapshot_sha256 = hashlib.sha256(raw).hexdigest()
    if snapshot_sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for {snapshot_name}")

    with BytesIO(raw) as file:
        metadata = file.readline().decode("utf-8").rstrip("\n")
        if not metadata.startswith("# fetched_at="):
            raise ValueError(f"Missing fetch timestamp in {snapshot_name}")
        fetched_at = metadata.removeprefix("# fetched_at=")
        datetime.fromisoformat(fetched_at)
        body_sha256 = hashlib.sha256(raw[file.tell():]).hexdigest()
        frame = pd.read_csv(file, header=[0, 1], index_col=0, parse_dates=[0])

    print(
        "Data source: Yahoo Finance daily prices and distributions (yfinance auto_adjust=False, "
        "query1.finance.yahoo.com and query2.finance.yahoo.com) embedded in config under "
        f"data.snapshots (decompressed sha256 {snapshot_sha256}); the script does not call "
        "yfinance, FRED or any host and reads no data_cache"
    )
    print(f"Input SHA-256: {body_sha256}")
    print(f"DATA_SHA256: {snapshot_sha256}")
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml", "key": "data.snapshots", "sha256": snapshot_sha256,
    }))
    return frame, fetched_at


def price_relatives(raw, settings):
    symbols = [*settings["universe"], settings["risk_free"]]
    start = pd.Timestamp(settings["dates"]["data_start"])
    end = pd.Timestamp(settings["dates"]["end"])
    if not isinstance(raw.index, pd.DatetimeIndex) or not raw.index.is_unique:
        raise ValueError("Price table must have unique session dates")
    raw = raw.sort_index().loc[start:end]
    if (raw.empty or raw.index[0] > start + pd.Timedelta(days=7)
            or raw.index[-1] < end - pd.Timedelta(days=7)):
        raise ValueError("Price coverage is shorter than the requested date range")

    opens = raw["Open"].reindex(columns=symbols)
    closes = raw["Close"].reindex(columns=symbols)
    quotes = np.stack([opens.to_numpy(), closes.to_numpy()])
    if not np.isfinite(quotes).all() or np.any(quotes <= 0):
        raise ValueError("Missing or invalid daily open/close in the fixed universe")

    distributions = raw["Dividends"].reindex(columns=symbols)
    if "Capital Gains" in raw.columns.get_level_values(0):
        distributions = distributions + raw["Capital Gains"].reindex(columns=symbols)
    if not np.isfinite(distributions.to_numpy()).all() or (distributions < 0).any().any():
        raise ValueError("Missing or invalid cash distribution field")

    # All terms share Yahoo's split adjustment, so common rescalings cancel.
    # The open leg uses only the preceding close, the current open and the
    # current ex-date distribution. The current close enters the intraday leg.
    overnight = (opens + distributions) / closes.shift(1)
    return overnight, closes / opens


def softmax(scores):
    shifted = np.exp(scores - scores.max())
    return shifted / shifted.sum()


def monthly_targets(overnight, intraday, model, lag, start):
    if not 1 <= model["min_memory_months"] <= model["memory_months"]:
        raise ValueError("Require a positive minimum memory and sufficient memory capacity")
    log_close_returns = np.log(overnight * intraday)
    features = []
    for window in model["lookbacks"]:
        rolling = log_close_returns.rolling(window)
        daily_vol = rolling.std(ddof=0).clip(lower=1e-8)
        features.extend([rolling.sum() / (daily_vol * np.sqrt(window)), np.log(daily_vol)])
    states = np.concatenate([feature.to_numpy() for feature in features], axis=1)

    sessions = overnight.index
    months = sessions.to_period("M")
    fill_rows = np.flatnonzero(months[1:] != months[:-1]) + 1
    fill_rows = fill_rows[fill_rows >= lag]
    signal_rows = fill_rows - lag
    label_ends = fill_rows[1:]
    stored_states = states[signal_rows[:-1]]
    ready_state = np.isfinite(stored_states).all(axis=1)
    log_overnight = np.log(overnight.to_numpy())
    log_intraday = np.log(intraday.to_numpy())

    target_rows = []
    weights_by_example = {}
    for fill_row, signal_row in zip(fill_rows, signal_rows):
        if sessions[fill_row] < start:
            continue
        # A label for month j is known at the open of month j+1. In
        # particular, the label ending at today's fill is still unavailable
        # at the signal close, regardless of the weight it might receive.
        known = np.searchsorted(label_ends, signal_row, side="right")
        examples = np.flatnonzero(ready_state[:known])[-model["memory_months"]:]
        query = states[signal_row]
        if len(examples) < model["min_memory_months"] or not np.isfinite(query).all():
            raise ValueError(f"Insufficient mature state history on {sessions[signal_row].date()}")

        keys = stored_states[examples]
        mean = keys.mean(axis=0)
        scale = keys.std(axis=0).clip(min=1e-8)
        keys = (keys - mean) / scale
        query = (query - mean) / scale
        key_norm = np.linalg.norm(keys, axis=1).clip(min=1e-8)
        query_norm = max(np.linalg.norm(query), 1e-8)
        probabilities = softmax(model["beta"] * (keys @ query) / (key_norm * query_norm))

        for example in examples:
            if example in weights_by_example:
                continue
            first, last = fill_rows[example], label_ends[example]
            realized = log_intraday[first:last] + log_overnight[first + 1:last + 1]
            risk = realized.std(axis=0).clip(min=1e-8) * np.sqrt(len(realized))
            score = model["label_scale"] * realized.sum(axis=0) / risk
            weights_by_example[example] = softmax(score)
        target_rows.append(probabilities @ np.asarray([weights_by_example[i] for i in examples]))

    return pd.DataFrame(
        target_rows, index=sessions[fill_rows][sessions[fill_rows] >= start],
        columns=overnight.columns,
    )


def rebalance_at_open(positions, cash, weights, fee_rate):
    before = float(positions.sum()) + cash
    # Find the largest invested amount for which purchases plus fees are
    # fully funded after sales. All prices are marked at the same open.
    affordable, upper = 0.0, before
    for _ in range(48):
        invested = (affordable + upper) / 2
        target = invested * weights
        due = float(target.sum()) + fee_rate * float(np.abs(target - positions).sum())
        if due <= before:
            affordable = invested
        else:
            upper = invested

    new_positions = affordable * weights
    traded = np.abs(new_positions - positions)
    cash = before - (float(new_positions.sum()) + fee_rate * float(traded.sum()))
    if cash < 0:
        raise RuntimeError("Rebalance spent more than the available value")
    return new_positions, cash, float(traded.sum()) / before, int(np.sum(traded > before * 1e-12))


def simulate(overnight, intraday, targets, fee_rate):
    # positions are the marked dollar values of fractional ETF positions.
    positions = np.zeros(len(overnight.columns))
    cash = 1.0
    previous_close_value = cash
    rows = []
    open_moves = overnight.to_numpy()
    intraday_moves = intraday.to_numpy()
    targets_by_session = dict(zip(targets.index, targets.to_numpy()))
    for row, day in enumerate(overnight.index):
        positions *= open_moves[row]
        turnover, trades = 0.0, 0
        if day in targets_by_session:
            positions, cash, turnover, trades = rebalance_at_open(
                positions, cash, targets_by_session[day], fee_rate,
            )
        positions *= intraday_moves[row]
        close_value = float(positions.sum()) + cash
        rows.append((close_value / previous_close_value - 1, turnover, trades))
        previous_close_value = close_value
    return pd.DataFrame(rows, index=overnight.index, columns=["return", "turnover", "n_trades"])


def metrics(daily, bill_returns):
    returns = daily["return"].to_numpy()
    if len(returns) < 2:
        raise ValueError("Each reported period needs at least two daily returns")
    wealth = np.r_[1.0, np.cumprod(1 + returns)]
    scale = np.sqrt(SESSIONS_PER_YEAR)
    vol = float(np.std(returns, ddof=1))
    excess = returns - bill_returns.loc[daily.index].to_numpy()
    excess_vol = float(np.std(excess, ddof=1))
    return {
        "cagr": float(wealth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1),
        "ann_vol": float(vol * scale),
        "sharpe": float(returns.mean() * scale / vol) if vol else None,
        "sharpe_excess": float(excess.mean() * scale / excess_vol) if excess_vol else None,
        "max_drawdown": float(np.min(wealth / np.maximum.accumulate(wealth) - 1)),
        "total_return": float(wealth[-1] - 1),
        "turnover": float(daily["turnover"].mean() * SESSIONS_PER_YEAR),
        "n_trades": int(daily["n_trades"].sum()),
    }


def period_metrics(daily, bill_returns, split):
    in_sample = daily.index < split
    return {
        "is": metrics(daily.loc[in_sample], bill_returns),
        "oos": metrics(daily.loc[~in_sample], bill_returns),
        "full": metrics(daily, bill_returns),
    }


def main():
    with Path("config.yaml").open(encoding="utf-8") as config_file:
        settings = yaml.safe_load(config_file)
    universe = settings["universe"]
    risk_free = settings["risk_free"]
    dates = settings["dates"]
    start, split = map(pd.Timestamp, [dates["backtest_start"], dates["oos_start"]])
    model = settings["model"]
    execution = settings["execution"]
    lag = execution["lag_sessions"]
    costs = [execution["commission_bps"], execution["slippage_bps"]]
    fee_rate = sum(costs) / 10_000
    alternatives = settings["robustness"]
    high_fee_rate = fee_rate * alternatives["cost_multiplier"]
    if lag < 1 or min(costs) < 0 or not 0 <= fee_rate <= high_fee_rate < 1:
        raise ValueError("Require a positive close-to-open lag and valid per-trade fees")
    if not pd.Timestamp(dates["data_start"]) < start < split <= pd.Timestamp(dates["end"]):
        raise ValueError("Require price warmup and chronological IS/OOS periods")
    if len(universe) < 2 or len(set(universe)) != len(universe) or risk_free in universe:
        raise ValueError("Require distinct ETF symbols and a separate BIL reference")

    raw, fetched_at = load_raw(settings)
    overnight, intraday = price_relatives(raw, settings)
    bill_returns = overnight[risk_free] * intraday[risk_free] - 1
    overnight, intraday = overnight[universe], intraday[universe]
    is_overnight = overnight.loc[overnight.index < split]
    is_intraday = intraday.loc[is_overnight.index]
    is_bill = bill_returns.loc[is_overnight.index]

    print(f"DATA_FETCHED_AT: {fetched_at}", flush=True)
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}")
    print(f"RAW_PRICE_RANGE: {raw.index.min().date()} to {raw.index.max().date()}")

    is_targets = monthly_targets(is_overnight, is_intraday, model, lag, start)
    alternatives_run = []
    for name in ("beta", "memory_months"):
        for value in alternatives[name]:
            variant = {**model, name: value}
            weights = monthly_targets(is_overnight, is_intraday, variant, lag, start)
            daily = simulate(is_overnight.loc[start:], is_intraday.loc[start:], weights, fee_rate)
            alternatives_run.append((f"{name}={value}", metrics(daily, is_bill)))
    high_cost_daily = simulate(
        is_overnight.loc[start:], is_intraday.loc[start:], is_targets, high_fee_rate,
    )
    alternatives_run.append((
        f"commission_and_slippage_multiplier={alternatives['cost_multiplier']}",
        metrics(high_cost_daily, is_bill),
    ))

    targets = monthly_targets(overnight, intraday, model, lag, start)
    pd.testing.assert_frame_equal(targets.loc[targets.index < split], is_targets)
    official = simulate(overnight.loc[start:], intraday.loc[start:], targets, fee_rate)
    reference_weights = pd.DataFrame(1 / len(universe), index=targets.index, columns=universe)
    reference = simulate(overnight.loc[start:], intraday.loc[start:], reference_weights, fee_rate)
    strategy_stats = period_metrics(official, bill_returns, split)
    benchmark_stats = period_metrics(reference, bill_returns, split)
    if min(strategy_stats["is"]["n_trades"], strategy_stats["oos"]["n_trades"]) <= 0:
        raise RuntimeError("The official run needs transactions in both report periods")

    print("LOOK_AHEAD_CHECK: prior close signal, mature labels, and later open sizing")
    print("LOOK_AHEAD_CHECK: close data available before fill, no macro publication inputs")
    print("LOOK_AHEAD_CHECK: forward ex-date adjustments from split-consistent price ratios")
    print("LOOK_AHEAD_CHECK: IS prefix matches full run; sensitivity uses only the IS prefix")
    print("ROBUSTNESS (IS only)")
    print("IS default " + json.dumps(strategy_stats["is"], allow_nan=False))
    for label, summary in alternatives_run:
        print(f"IS {label} " + json.dumps(summary, allow_nan=False))
    print(f"PARAM_COMBOS_TRIED: {1 + len(alternatives_run)}")
    print("已回测 · 确有交易 · 待审查")
    for period in strategy_stats:
        print(f"{period.upper()} strategy " + json.dumps(strategy_stats[period], allow_nan=False))
        print(f"{period.upper()} benchmark " + json.dumps(benchmark_stats[period], allow_nan=False))
    result = {
        "strategy": settings["strategy"],
        "data_range": [official.index[0].date().isoformat(), official.index[-1].date().isoformat()],
        **strategy_stats,
        "benchmark": {"name": "Monthly equal-weight ETFs", **benchmark_stats},
    }
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(14 * 60)
    main()
